import{_ as n,a0 as l,w as a,s as u,ao as s,I as i,x as t,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"戴文的Linux內核專題：13 配置內核(9) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：13 配置內核(9) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：13 配置內核(9) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：13 配置內核(9) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/13 The Linux Kernel--Configuring the Kernel Part 9","title":"戴文的Linux內核專題：13 配置內核(9)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/13 The Linux Kernel--Configuring the Kernel Part 9.md","filePath":"[post].md"}'),g={name:"The Linux Kernel/13 The Linux Kernel--Configuring the Kernel Part 9.md"};function A(c,e,P,d,f,C){const p=l("Link");return a(),u("div",null,[e[11]||(e[11]=s('<h1 id="戴文的linux內核專題-13-配置內核-9" tabindex="-1">戴文的Linux內核專題：13 配置內核(9) <a class="header-anchor" href="#戴文的linux內核專題-13-配置內核-9" aria-label="Permalink to “戴文的Linux內核專題：13 配置內核(9)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.498/" alt=""></p><p>Novell的網絡協議IPX通常用於Windows系統和NetWare服務器(The IPX protocol)。IPX代表網間分組交換(Internetwork Packet Exchange)。這是一個網絡層協議通常與傳輸層的SPX協議同時使用。</p><p>為了使NetWare服務器在服務的網絡中有相同的IPX地址，啓用下一個特性(IPX: Full internal IPX network)。不然，每個網絡都會看到服務器一個不同的IPX地址。</p><p>注意：IPX協議使用IPX尋址，而不是IP尋址。IP地址不是計算機網絡中唯一的網絡地址。</p><p>對於在Apple網絡中的Linux系統，需要啓用Appletalk(Appletalk protocol support)。蘋果計算機和蘋果打印機通常使用Appletalk在網絡間通信。Appletalk不需要一台中心路由器/服務器並且網絡系統是即插即用的。</p><p>在Appletalk網絡中Linux系統需要使用IP需要&quot;Appletalk interfaces support&quot;(AppleTalk接口支持)。</p><p>下一個特性允許用户在Appletalk中使用IP隧道(Appletalk-IP driver support)。</p><p>接下來，這個特性允許IP包被封裝成Apppletalk幀(IP to Appletalk-IP Encapsulation support)。在網絡中，幀是一種標記包的開始和結束的特殊序列位。這個特性會將IP包放在Appletalk包內部。</p><p>這個特性允許為先前的特性解包(Appletalk-IP to IP Decapsulation support)。解包器會將IP包從Appletalk包中拿出。</p><p>這是另外一個協議層稱為&quot;X.25&quot; (CCITT X.25 Packet Layer)。這個協議層通常用於非常大的網絡，就像國家公網。許多銀行使用這個在他們的擴展網絡系統裏。X25(拼成&quot;X25&quot;或&quot;X.25&quot;)網絡擁有將進入數據包打包的包分組交換機。X25正在被更簡單的IP協議代替。X25是一個不如TCP/IP有效率的舊協議，但是一些公司發現它在大型、複雜的網絡中很有用。</p><p>LAPB是用於X.25的數據鏈路層(LAPB Data Link Driver)。如果上面的啓用了，那麼這也應該同時啓用。LAPB代表的是&quot;Link Access Procedure Balanced&quot;(鏈路訪問過程平衡)。LAPB同樣也用於以太網和X.21網卡中(這裏沒有打錯)。X.21是用於物理層(硬件),X.25用於網絡層。LPAB會檢查錯誤並確保包被放回正確的序列中。</p><p>Nokia調製解調器使用的電話網絡協議通常稱作&quot;PhoNet&quot;(Phonet protocols family)。Linux計算機遠程控制Nokia電話機需要這個特性。</p><p>下一個網絡通常是用於不同自動設備間的小型無線連接(IEEE Std 802.15.4 Low-Rate Wireless Personal Area Networks support)。802.15.4是一種需要很少電量的簡單低數據率協議。這個無線協議最大可擴展到10米。這在通過無線網絡連接機器人傳感器時是很有用的。任何不該有線纜的機械可能都會從這個代替了繩子的本地無線網絡中獲益。</p><p>如果啓用了上面的特性，那麼最好明智地啓用這個IPv6 壓縮特性(6lowpan support over IEEE 802.15.4)。</p><p>支持物理層 IEEE 802.15.4協議的SoftMac設備可以啓用這個特性(Generic IEEE 802.15.4 Soft Networking Stack (mac802154))。</p><p>當有許多包需要傳輸時，內核必須決定先發送哪一個(它們不能一次全部發送)，所以這個特性幫助內核區分包的優先級(QoS and/or fair queuing)。如果不啓用這個，那麼內核會使用&quot;first come, first serve approach&quot;(&quot;誰先到，誰先服務&quot;)。這可能意味着緊急的網絡消息需要等待才能輪到它們傳輸。</p><p>在有數據中心服務器的網絡中，這個特性強烈建議啓用(Data Center Bridging support)。這個特性增強了以太網對數據中心網絡的連接。</p><p>DNS查詢可以在下一個選項中啓用(DNS Resolver support)。大多數存儲DNS緩存的系統允許計算機無需DNS服務器的輔助下執行DNS查詢。</p><p>接下來是另一個用於多跳專用網狀網絡(B.A.T.M.A.N. Advanced Meshing Protocol)。&quot;B.A.T.M.A.N.&quot;代表&quot;better approach to mobile ad-hoc networking&quot;(更好接入移動專用網絡)。這個工作與有線和無線網絡。專用網絡沒有中心像路由器這類中心設置。每台網絡上的設備就像個一台路由器。網狀網絡是一個簡單的概念。每個節點必須路由發送給它的數據。在這個網狀網絡中，每台計算機連接到全部或幾乎全部其他網絡設備。當這樣的網絡畫在紙上成為一張地圖時，這個網絡看上去就像一張網。</p><p>當許多網狀節點連接到相同的LAN和網時，一些網絡信號可能會迴環(Bridge Loop Avoidance)(避免橋迴環)。這個特性可以避免此類的迴環。這些迴環可能永遠不會結束或者降低性能。避免這樣的迴環被稱為&quot;Bridge Loop Avoidance (BLA)&quot;。</p><p>分佈式ARP表(Distributed ARP Tables (DAT))被用於增強ARP在稀疏無線網狀網絡的可靠性(Distributed ARP Table)。</p><p>BATMAN協議有些開發者需要用到的調式特性(B.A.T.M.A.N. Debugging)。對於任何調試特性，通常最好禁用它來節省空間以及得到一個更好優化後的內核。</p><p>虛擬化環境可以從&quot;Open vSwitch&quot;中得益。這是一個多層以太網交換機。Open vSwitch支持大量的協議。</p><p>虛擬機、hypervisor、主機之間的網絡連接需要&quot;virtual socket protocol&quot;。這個類似於TCP/IP.這些套接字就像其他網絡套接字，但是它們針對虛擬機。這允許客户機系統擁有一個與主機的網絡連接。</p><p>這是一個可以管理網絡優先級的cgroup子系統(Network priority cgroup)。這允許控制組(cgroup)根據發送應用設置網絡流量優先級。</p><p>BPF過濾器由解釋器處理，但是內核可以執行原生BPF過濾通過這個(enable BPF Just In Time compiler)。BPF代表的是&quot;Berkeley Packet Filter&quot;(伯克利報過濾器)。這允許計算機系統支持原生鏈路層包。</p><p>下面，我們有兩個網絡測試工具。第一個是&quot;Packet Generator&quot;(包生成器)，這用於測試網絡時注射數據包(製造空包)。第二個，允許設置一個警報系統，當數據包丟失時警告用户/系統(Network packet drop alerting service)。</p><p>Linux內核可以用於無線電系統或者遠程控制它們。&quot;Amateur Radio AX.25 Level 2 protocol&quot;用於計算機通過無線電通信。這個無線電協議可以在其他許多的協議中支持TCP/IP。</p><p>為了放置在AX.25網絡中衝突，啓用DAMA(AX.25 DAMA Slave support)。至今為止，Linux還不能作為DAMA的服務器，但是可以作為DAMA的客户端。DAMA代表&quot;Demand Assigned Multiple Access&quot;(按需分配多址訪問)。DAMA分配網絡流量到特定的信道中去。</p><p>NET/ROM是AX.25的路由層。(Amateur Radio NET/ROM protocol)。</p><p>NET/ROM的一個替代是&quot;Packet Layer Protocol (PLP)&quot;(包層協議)，它可以運行在AX.25的頂端(Amateur Radio X.25 PLP (Rose))。</p><p>控制器局域網絡(Controller Area Network (CAN))總線需要這個驅動(CAN bus subsystem support)。CAN總線是一種用於不同目的的串行協議。</p><p>使用這個特性(Raw CAN Protocol (raw access with CAN-ID filtering))，CAN總線可以通過BSD套接字API訪問</p><p>內核中有用於CAN協議的廣播管理(Broadcast Manager CAN Protocol (with content filtering))。這個管理提供了很多控制，包括內容過濾。</p><p>為了讓Linux盒子成為一個CAN路由器和/或者網關，需要這個特性(CAN Gateway/Router (with netlink configuration))。</p><p>注意：網關是兩個或者更多網絡的接口設備，它提供不同的協議。一個簡單的定義可以是&quot;網關是一個協議轉換器。&quot;</p><p>注意：路由器轉發網絡流量和連接使用相同協議網絡。</p><p>如果啓用了(一些選項)，Linux內核可以支持很多CAN設備(主要是控制器)和接口。所有的CAN驅動都是對於這些設備的不同品牌和型號。在配置工具中，它們有以下這些標題。</p><ul><li>Virtual Local CAN Interface (vcan)</li><li>Serial / USB serial CAN Adaptors (slcan)</li><li>Platform CAN drivers with Netlink support</li><li>Enable LED triggers for Netlink based drivers</li><li>Microchip MCP251x SPI CAN controllers</li><li>Janz VMOD-ICAN3 Intelligent CAN controller</li><li>Intel EG20T PCH CAN controller</li><li>Philips/NXP SJA1000 devices</li><li>Bosch C_CAN/D_CAN devices</li><li>Bosch CC770 and Intel AN82527 devices</li><li>CAN USB interfaces</li><li>Softing Gmbh CAN generic support</li><li>Softing Gmbh CAN pcmcia cards</li></ul><p>像Linux中的其他許多特性，CAN設備同樣可以啓用調試能力(CAN devices debugging messages)。再説一次，記住你內核的目的，你需要調試還是需要性能?</p><p>Linux內核同樣支持紅外線信號協議IrDA (infrared) subsystem support)。IrDa代表的是 &quot;Infrared Data Associations&quot;(紅外數據協會)；這是紅外信號的標準。</p><p>許多人如今想要藍牙特性(Bluetooth subsystem support)。</p><p>RxRPC會話套接字可以啓用(RxRPC session sockets)。這些套接字使用RxRPC協議運載網絡連接。RxRPC運行於UDP的頂部。</p><p>如果啓用的話，Linux內核可以支持&quot;RxRPC dynamic debugging&quot;(RxRPC 動態調試)。</p><p>RxRPC擁有kerberos 4和AFS kaserver安全特性可以啓用(RxRPC Kerberos security)。Kerberos是一種每個網絡設備在傳輸任何數據前都被需要證明彼此的身份的驗證協議。</p><p>對於電腦的無線網絡設備像Wifi，配置工具需要啓用無線局域網(802.11)設備(cfg80211 - wireless configuration API)。cfg80211代表&quot;Configuration 802.11&quot;(配置 802.11)。802.11是一種無線規範。</p><p>&quot;nl80211 testmode command&quot;是用於校準並且/或驗證的實用工具，它無線設備芯片上執行這些任務。</p><p>下一個設置允許用户&quot;enable developer warnings&quot;(啓用開發者警告)對於cfg80211設備。</p><p>下面，&quot;cfg80211 regulatory debugging&quot;(cfg80211調控調試)可以啓用。</p><p>下面的設定是&quot;cfg80211 certification onus&quot;(cfg80211證書義務)。</p><p>應該為cfg80211兼容設備啓用省電特性(enable powersave by default)。</p><p>cfg80211支持debugfs入口(cfg80211 DebugFS entries)。</p><p>無線設備有它們遵守的調整規則；這些被存儲在資料庫中(use statically compiled regulatory rules database)(使用靜態編譯的調整規則資料庫)</p><p>一些使用基於cfg80211的驅動擴展可能需要使用一個老的用户空間。這個特性允許這個行為(cfg80211 wireless extensions compatibility)(cfg80211 無線擴展兼容)。</p><p>lib80211可以提供調試特性(lib80211 debugging messages)。</p><p>獨立於硬件的IEEE 802.11標準可以啓用(Generic IEEE 802.11 Networking Stack (mac80211))。mac80211是一種用於編寫softMAC無線設備驅動的框架。SoftMac允許很好地控制和配置設備。</p><p>下一個特性允許mac80211使用PID控制器管理TX(發送)速率(PID controller based rate control algorithm)(PID控制器基於速率控制算法)。TX單位是BFS(Bits per minute)(位/秒)。特別地，這個特性是用於控制數據流速率的算法。</p><p>另外一個相同特性的算法叫做&quot;Minstrel&quot;。這是一個比TX速率管理算法更精確和有效的算法。</p><p>Minstrel同樣支持802.11n(Minstrel 802.11n support)。</p><p>由於有兩種TX速率控制算法，但只能使用一種。所喲必須設備一個默認的(Default rate control algorithm (Minstrel))。通常地，最好選擇Minstrel作為默認。</p><p>802.11s網狀網絡草案可以在內核中啓用(Enable mac80211 mesh networking (pre-802.11s) support)。802.11s草案是網狀網絡的無線標準。</p><p>對於支持這個特性的設備，對於不同包流量時間的LED除法器特性可以啓用(Enable LED triggers)。在我的以太網設備商上，當端口是活躍時LED燈會點亮。這些驅動可以是這些LED在包流量時間下工作。</p><p>mac80211同樣支持debugfs特性(Export mac80211 internals in DebugFS)。</p><p>這是一個獨立於典型日誌系統收集mac80211調試信息的特性(Trace all mac80211 debug messages)。</p><p>這是另外一組mac80211調試特性，但是這些使用的是典型日誌系統(Select mac80211 debugging features ---&gt;)。在這個菜單，選擇你需要的調試特性。</p><p>在下一篇文章中，我們還有更多的需要配置。</p><hr>',68)),i("p",null,[e[1]||(e[1]=t("via: ",-1)),o(p,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-9.4568/"},{default:r(()=>[...e[0]||(e[0]=[t("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-9.4568/",-1)])]),_:1})]),i("p",null,[e[4]||(e[4]=t("譯者：",-1)),o(p,{href:"https://github.com/geekpi"},{default:r(()=>[...e[2]||(e[2]=[t("geekpi",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),o(p,{href:"https://github.com/wxy"},{default:r(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=t("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),o(p,{href:"http://linux.cn/"},{default:r(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const L=n(g,[["render",A]]);export{x as __pageData,L as default};
